import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    if n == 1:
        print(0)
        return

    adj = [[] for _ in range(n + 1)]
    degree = [0] * (n + 1)

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)
        degree[u] += 1
        degree[v] += 1

    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            comp = []
            q = deque([i])
            visited[i] = True
            while q:
                u = q.popleft()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        q.append(v)
            components.append(comp)

    num_components = len(components)
    if num_components == 1:
        print(0)
        return

    component_id = [-1] * (n + 1)
    for idx, comp in enumerate(components):
        for node in comp:
            component_id[node] = idx

    parent = list(range(num_components))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        parent[px] = py
        return True

    edges_to_check = []
    for u in range(1, n + 1):
        for v in adj[u]:
            if u < v:
                cu, cv = component_id[u], component_id[v]
                if cu != cv:
                    edges_to_check.append((cu, cv))

    edges_to_check.sort()

    mst_weight = 0
    components_connected = num_components

    for cu, cv in edges_to_check:
        if union(cu, cv):
            mst_weight += 1
            components_connected -= 1
            if components_connected == 1:
                break

    print(mst_weight)

if __name__ == "__main__":
    solve()
